2.1 Distance to USA border

library(tidyverse)
library(sf)
library(units)
library(flextable)


Attaching package: 'flextable'


The following object is masked from 'package:purrr':

    compose

usa_border &lt;- states |&gt;
  st_union() |&gt;                    
  st_cast("MULTILINESTRING")       

uscities_sf &lt;- uscities_sf |&gt;
  st_transform(crs = eqdc)
# calculate distance from each city to the USA border
uscities_sf &lt;- uscities_sf |&gt;
  mutate(dist_to_usa_border_km = set_units(st_distance(geometry, usa_border), "km"))

# 5 cities farthest from the USA border
uscities_sf |&gt;
  st_drop_geometry() |&gt;
  select(city, state_id, dist_to_usa_border_km) |&gt;
  arrange(desc(dist_to_usa_border_km)) |&gt;
  slice_head(n = 5) |&gt;
  flextable()

