2.3 Distance to Mexico (km)

library(rnaturalearth)

countries &lt;- ne_countries(scale = "small", returnclass = "sf")

mexico_border &lt;- countries |&gt;
  filter(sovereignt == "Mexico") |&gt;
  st_union() |&gt;
  st_cast("MULTILINESTRING") |&gt;
  st_transform(5070)

uscities_sf &lt;- uscities_sf |&gt;
  st_transform(crs = 5070)

uscities_sf &lt;- uscities_sf |&gt;
  mutate(dist_to_mexico_km = set_units(st_distance(geometry, mexico_border), "km"))

uscities_sf |&gt;
  st_drop_geometry() |&gt;
  select(city, state_id, dist_to_mexico_km) |&gt;
  arrange(desc(dist_to_mexico_km)) |&gt;
  slice_head(n = 5) |&gt;
  flextable()

