Distance to Canada (km)

library(sf)
library(dplyr)
library(units)
library(rnaturalearth)

# Load countries
countries &lt;- ne_countries(scale = "small", returnclass = "sf")

# Create Canada border and transform to match city CRS
canada_border &lt;- countries |&gt;
  filter(sovereignt == "Canada") |&gt;
  st_union() |&gt;
  st_cast("MULTILINESTRING") |&gt;
  st_transform(5070)

uscities_sf &lt;- uscities_sf |&gt;
  st_transform(5070)

uscities_sf &lt;- uscities_sf |&gt;
  mutate(dist_to_canada_km = set_units(st_distance(geometry, canada_border), "km"))

uscities_sf |&gt;
  st_drop_geometry() |&gt;
  select(city, state_id, dist_to_canada_km) |&gt;
  arrange(desc(dist_to_canada_km)) |&gt;
  slice_head(n = 5) |&gt;
  flextable()

